Here's a clean, modern **Todo List App** built with HTML, CSS, and JavaScript — all in one file. It includes adding, completing, deleting, filtering, and local storage persistence.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Todo List</title>
  <style>
    /* ── Reset & Base ────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      padding: 40px 16px;
    }

    /* ── Container ───────────────────────────────── */
    .app {
      width: 100%;
      max-width: 520px;
      align-self: flex-start;
    }

    h1 {
      color: #fff;
      font-size: 2.2rem;
      text-align: center;
      margin-bottom: 24px;
      text-shadow: 0 2px 8px rgba(0,0,0,.2);
    }

    /* ── Input Area ──────────────────────────────── */
    .input-row {
      display: flex;
      gap: 10px;
      margin-bottom: 16px;
    }

    .input-row input {
      flex: 1;
      padding: 14px 18px;
      border: none;
      border-radius: 12px;
      font-size: 1rem;
      background: #fff;
      box-shadow: 0 4px 16px rgba(0,0,0,.1);
      outline: none;
      transition: box-shadow .2s;
    }

    .input-row input:focus {
      box-shadow: 0 4px 20px rgba(102,126,234,.45);
    }

    .input-row button {
      padding: 14px 22px;
      border: none;
      border-radius: 12px;
      background: #fff;
      color: #667eea;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 4px 16px rgba(0,0,0,.1);
      transition: background .2s, color .2s;
    }

    .input-row button:hover { background: #667eea; color: #fff; }

    /* ── Filters ─────────────────────────────────── */
    .filters {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-bottom: 16px;
    }

    .filters button {
      padding: 8px 18px;
      border: 2px solid rgba(255,255,255,.5);
      border-radius: 20px;
      background: transparent;
      color: #fff;
      font-size: .85rem;
      font-weight: 600;
      cursor: pointer;
      transition: .2s;
    }

    .filters button:hover,
    .filters button.active {
      background: #fff;
      color: #667eea;
      border-color: #fff;
    }

    /* ── Stats ────────────────────────────────────── */
    .stats {
      text-align: center;
      color: rgba(255,255,255,.85);
      font-size: .85rem;
      margin-bottom: 12px;
    }

    /* ── Todo List ────────────────────────────────── */
    .todo-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .todo-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 18px;
      background: #fff;
      border-radius: 12px;
      box-shadow: 0 2px 10px rgba(0,0,0,.08);
      animation: slideIn .3s ease;
    }

    @keyframes slideIn {
      from { opacity: 0; transform: translateY(-8px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    /* checkbox */
    .todo-item .check {
      width: 24px; height: 24px;
      border: 2px solid #ccc;
      border-radius: 50%;
      cursor: pointer;
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: .2s;
    }

    .todo-item .check:hover { border-color: #667eea; }

    .todo-item.done .check {
      background: #667eea;
      border-color: #667eea;
    }

    .todo-item.done .check::after {
      content: '✓';
      color: #fff;
      font-size: .85rem;
      font-weight: 700;
    }

    /* text */
    .todo-item .text {
      flex: 1;
      font-size: 1rem;
      color: #333;
      word-break: break-word;
      transition: .2s;
    }

    .todo-item.done .text {
      text-decoration: line-through;
      color: #aaa;
    }

    /* delete */
    .todo-item .delete {
      width: 28px; height: 28px;
      border: none; background: none;
      font-size: 1.2rem;
      color: #ccc;
      cursor: pointer;
      border-radius: 6px;
      transition: .2s;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .todo-item .delete:hover { color: #e74c3c; background: #fdecea; }

    /* ── Empty State ─────────────────────────────── */
    .empty {
      text-align: center;
      padding: 40px 0;
      color: rgba(255,255,255,.7);
      font-size: 1rem;
    }

    .empty span { font-size: 2rem; display: block; margin-bottom: 8px; }
  </style>
</head>
<body>
  <div class="app">
    <h1>📝 Todo List</h1>

    <div class="input-row">
      <input id="todoInput" type="text" placeholder="What needs to be done?" />
      <button id="addBtn">Add</button>
    </div>

    <div class="filters">
      <button class="active" data-filter="all">All</button>
      <button data-filter="active">Active</button>
      <button data-filter="done">Done</button>
    </div>

    <div class="stats" id="stats"></div>

    <ul class="todo-list" id="todoList"></ul>
    <div class="empty" id="empty" style="display:none">
      <span>🎉</span>Nothing here yet — add a task!
    </div>
  </div>

  <script>
    // ── State ───────────────────────────────────────
    let todos = JSON.parse(localStorage.getItem('todos') || '[]');
    let filter = 'all';

    const input    = document.getElementById('todoInput');
    const addBtn   = document.getElementById('addBtn');
    const list     = document.getElementById('todoList');
    const empty    = document.getElementById('empty');
    const statsEl  = document.getElementById('stats');
    const filterBtns = document.querySelectorAll('.filters button');

    // ── Render ──────────────────────────────────────
    function render() {
      const filtered = todos.filter(t =>
        filter === 'all' ? true : filter === 'done' ? t.done : !t.done
      );

      list.innerHTML = '';

      if (filtered.length === 0) {
        empty.style.display = 'block';
        empty.querySelector('span').textContent = todos.length ? '🔍' : '🎉';
        empty.childNodes[1].textContent = todos.length
          ? ' No matching tasks'
          : ' Nothing here yet — add a task!';
      } else {
        empty.style.display = 'none';
      }

      filtered.forEach(todo => {
        const li = document.createElement('li');
        li.className = 'todo-item' + (todo.done ? ' done' : '');

        li.innerHTML = `
          <div class="check" data-id="${todo.id}"></div>
          <span class="text">${escapeHTML(todo.text)}</span>
          <button class="delete" data-id="${todo.id}">✕</button>
        `;

        li.querySelector('.check').addEventListener('click', () => toggleTodo(todo.id));
        li.querySelector('.delete').addEventListener('click', () => deleteTodo(todo.id));

        list.appendChild(li);
      });

      // stats
      const doneCount = todos.filter(t => t.done).length;
      statsEl.textContent = `${todos.length} task${todos.length !== 1 ? 's' : ''} · ${doneCount} done`;

      save();
    }

    // ── Actions ─────────────────────────────────────
    function addTodo() {
      const text = input.value.trim();
      if (!text) return;
      todos.unshift({ id: Date.now(), text, done: false });
      input.value = '';
      input.focus();
      render();
    }

    function toggleTodo(id) {
      const t = todos.find(t => t.id === id);
      if (t) t.done = !t.done;
      render();
    }

    function deleteTodo(id) {
      todos = todos.filter(t => t.id !== id);
      render();
    }

    function setFilter(f) {
      filter = f;
      filterBtns.forEach(b => b.classList.toggle('active', b.dataset.filter === f));
      render();
    }

    function save() {
      localStorage.setItem('todos', JSON.stringify(todos));
    }

    function escapeHTML(str) {
      const d = document.createElement('div');
      d.textContent = str;
      return d.innerHTML;
    }

    // ── Events ──────────────────────────────────────
    addBtn.addEventListener('click', addTodo);
    input.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });
    filterBtns.forEach(b => b.addEventListener('click', () => setFilter(b.dataset.filter)));

    // ── Init ────────────────────────────────────────
    render();
  </script>
</body>
</html>
```

---

### ✨ Features at a glance

| Feature | Detail |
|---|---|
| **Add tasks** | Type + press **Enter** or click **Add** |
| **Complete tasks** | Click the circle checkbox to toggle ✓ |
| **Delete tasks** | Click the **✕** button |
| **Filter** | Switch between **All / Active / Done** |
| **Persistence** | Saved to `localStorage` — survives page refresh |
| **Stats bar** | Shows total tasks & how many are done |
| **Responsive** | Works on mobile and desktop |
| **Animations** | Smooth slide-in when tasks are added |
| **Empty states** | Friendly messages when no tasks match |

Save the code as **`todo.html`** and open it in any browser — no build tools needed!

Here's a complete, modern **Todo List App** in a single HTML file with CSS and JavaScript:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Todo List App</title>
  <style>
    /* ── Reset & Base ── */
    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      padding: 40px 16px;
    }

    /* ── Container ── */
    .container {
      width: 100%;
      max-width: 520px;
      align-self: flex-start;
    }

    h1 {
      color: #fff;
      text-align: center;
      font-size: 2.2rem;
      margin-bottom: 24px;
      text-shadow: 0 2px 8px rgba(0,0,0,.2);
    }

    /* ── Input Area ── */
    .input-area {
      display: flex;
      gap: 10px;
      margin-bottom: 20px;
    }

    .input-area input {
      flex: 1;
      padding: 14px 18px;
      border: none;
      border-radius: 12px;
      font-size: 1rem;
      outline: none;
      box-shadow: 0 4px 16px rgba(0,0,0,.15);
      transition: box-shadow .2s;
    }

    .input-area input:focus {
      box-shadow: 0 4px 20px rgba(0,0,0,.25);
    }

    .input-area button {
      padding: 14px 22px;
      background: #ff6b6b;
      color: #fff;
      border: none;
      border-radius: 12px;
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
      box-shadow: 0 4px 16px rgba(255,107,107,.4);
      transition: background .2s, transform .1s;
    }

    .input-area button:hover  { background: #ee5a5a; }
    .input-area button:active { transform: scale(.96); }

    /* ── Filters ── */
    .filters {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-bottom: 18px;
    }

    .filters button {
      padding: 8px 18px;
      border: 2px solid rgba(255,255,255,.5);
      background: transparent;
      color: #fff;
      border-radius: 20px;
      font-size: .85rem;
      cursor: pointer;
      transition: .2s;
    }

    .filters button.active,
    .filters button:hover {
      background: #fff;
      color: #764ba2;
      border-color: #fff;
    }

    /* ── Stats ── */
    .stats {
      text-align: center;
      color: rgba(255,255,255,.85);
      font-size: .9rem;
      margin-bottom: 14px;
    }

    /* ── Todo List ── */
    .todo-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .todo-item {
      display: flex;
      align-items: center;
      gap: 12px;
      background: #fff;
      padding: 14px 16px;
      border-radius: 12px;
      box-shadow: 0 3px 12px rgba(0,0,0,.1);
      animation: slideIn .3s ease;
    }

    @keyframes slideIn {
      from { opacity: 0; transform: translateY(-10px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    /* checkbox */
    .todo-item input[type="checkbox"] {
      width: 22px; height: 22px;
      accent-color: #764ba2;
      cursor: pointer;
      flex-shrink: 0;
    }

    .todo-item .text {
      flex: 1;
      font-size: 1rem;
      word-break: break-word;
      transition: .25s;
    }

    .todo-item.done .text {
      text-decoration: line-through;
      color: #aaa;
    }

    /* edit input */
    .todo-item .edit-input {
      flex: 1;
      padding: 6px 10px;
      border: 2px solid #764ba2;
      border-radius: 8px;
      font-size: 1rem;
      outline: none;
    }

    /* action buttons */
    .todo-item .actions {
      display: flex;
      gap: 6px;
      flex-shrink: 0;
    }

    .todo-item .actions button {
      width: 34px; height: 34px;
      border: none;
      border-radius: 8px;
      cursor: pointer;
      font-size: 1rem;
      transition: .2s;
      display: grid;
      place-items: center;
    }

    .btn-edit   { background: #ffeaa7; color: #6c5300; }
    .btn-edit:hover { background: #fdda6e; }
    .btn-delete { background: #fab1a0; color: #6e1600; }
    .btn-delete:hover { background: #f38375; }
    .btn-save   { background: #a0e8af; color: #1a5c28; }
    .btn-save:hover { background: #7ce08e; }

    /* ── Empty State ── */
    .empty {
      text-align: center;
      color: rgba(255,255,255,.7);
      font-size: 1.1rem;
      margin-top: 40px;
    }

    /* ── Clear-completed ── */
    .clear-btn {
      display: block;
      margin: 22px auto 0;
      padding: 10px 24px;
      background: rgba(255,255,255,.15);
      color: #fff;
      border: 2px solid rgba(255,255,255,.4);
      border-radius: 10px;
      font-size: .9rem;
      cursor: pointer;
      transition: .2s;
    }
    .clear-btn:hover { background: rgba(255,255,255,.3); }
  </style>
</head>
<body>

<div class="container">
  <h1>📝 Todo List</h1>

  <!-- Input -->
  <div class="input-area">
    <input type="text" id="todoInput" placeholder="What needs to be done?" />
    <button id="addBtn">Add</button>
  </div>

  <!-- Filters -->
  <div class="filters">
    <button class="active" data-filter="all">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="completed">Completed</button>
  </div>

  <!-- Stats -->
  <p class="stats" id="stats"></p>

  <!-- List -->
  <ul class="todo-list" id="todoList"></ul>

  <!-- Empty state -->
  <p class="empty" id="emptyMsg" style="display:none">🎉 No tasks yet — add one above!</p>

  <!-- Clear completed -->
  <button class="clear-btn" id="clearBtn" style="display:none">Clear completed</button>
</div>

<script>
  // ── State ──
  let todos = JSON.parse(localStorage.getItem('todos')) || [];
  let filter = 'all';

  // ── DOM refs ──
  const input    = document.getElementById('todoInput');
  const addBtn   = document.getElementById('addBtn');
  const list     = document.getElementById('todoList');
  const statsEl  = document.getElementById('stats');
  const emptyMsg = document.getElementById('emptyMsg');
  const clearBtn = document.getElementById('clearBtn');
  const filterBtns = document.querySelectorAll('.filters button');

  // ── Save & Render ──
  function save() {
    localStorage.setItem('todos', JSON.stringify(todos));
  }

  function render() {
    const filtered = todos.filter(t => {
      if (filter === 'active')    return !t.done;
      if (filter === 'completed') return  t.done;
      return true;
    });

    list.innerHTML = '';

    filtered.forEach(todo => {
      const li = document.createElement('li');
      li.className = 'todo-item' + (todo.done ? ' done' : '');

      li.innerHTML = `
        <input type="checkbox" ${todo.done ? 'checked' : ''} />
        <span class="text">${escapeHTML(todo.text)}</span>
        <div class="actions">
          <button class="btn-edit" title="Edit">✏️</button>
          <button class="btn-delete" title="Delete">🗑️</button>
        </div>
      `;

      // Toggle done
      li.querySelector('input[type="checkbox"]').addEventListener('change', () => {
        todo.done = !todo.done;
        save(); render();
      });

      // Delete
      li.querySelector('.btn-delete').addEventListener('click', () => {
        todos = todos.filter(t => t.id !== todo.id);
        save(); render();
      });

      // Edit
      li.querySelector('.btn-edit').addEventListener('click', () => startEdit(li, todo));

      list.appendChild(li);
    });

    // Stats
    const active    = todos.filter(t => !t.done).length;
    const completed = todos.filter(t =>  t.done).length;
    statsEl.textContent = `${active} active · ${completed} completed · ${todos.length} total`;

    // Empty state
    emptyMsg.style.display = filtered.length === 0 ? 'block' : 'none';

    // Clear button
    clearBtn.style.display = completed > 0 ? 'block' : 'none';
  }

  // ── Inline edit ──
  function startEdit(li, todo) {
    const textSpan = li.querySelector('.text');
    const actions  = li.querySelector('.actions');

    const editInput = document.createElement('input');
    editInput.className = 'edit-input';
    editInput.value = todo.text;
    textSpan.replaceWith(editInput);
    editInput.focus();

    actions.innerHTML = `<button class="btn-save" title="Save">💾</button>`;

    const saveEdit = () => {
      const val = editInput.value.trim();
      if (val) { todo.text = val; save(); }
      render();
    };

    actions.querySelector('.btn-save').addEventListener('click', saveEdit);
    editInput.addEventListener('keydown', e => { if (e.key === 'Enter') saveEdit(); });
  }

  // ── Add todo ──
  function addTodo() {
    const text = input.value.trim();
    if (!text) return;
    todos.push({ id: Date.now(), text, done: false });
    input.value = '';
    save(); render();
    input.focus();
  }

  addBtn.addEventListener('click', addTodo);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });

  // ── Filters ──
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      filter = btn.dataset.filter;
      render();
    });
  });

  // ── Clear completed ──
  clearBtn.addEventListener('click', () => {
    todos = todos.filter(t => !t.done);
    save(); render();
  });

  // ── Helper ──
  function escapeHTML(str) {
    const d = document.createElement('div');
    d.textContent = str;
    return d.innerHTML;
  }

  // ── Init ──
  render();
</script>

</body>
</html>
```

